  "l4-pym-regex": { en: ["Validators: fullmatch. Extractors: search. Confusing them opens holes.", "Name every group you will read later — group('user') beats group(3) forever."], bn: ["Validator: fullmatch। Extractor: search। গুলিয়ে ফেললে ছিদ্র খোলে।", "পরে পড়বে এমন প্রতিটি group-এর নাম দাও — group('user') চিরদিন group(3)-কে হারায়।"] },
  "l4-pym-datetime": { en: ["Write the format by looking at the stamp, not from memory.", "Record the timezone with the timestamp whenever the source gives one."], bn: ["Stamp-এর দিকে তাকিয়ে format লেখো, স্মৃতি থেকে নয়।", "উৎস দিলে timestamp-এর সঙ্গে timezone record করো।"] },
