  "l4-pym-sockets": { en: ["Port 0 + getsockname for every teaching/test server — never clash with a real service.", "Design the framing (length or delimiter) before the first recv."], bn: ["প্রতিটি শিক্ষণ/test server-এর জন্য port 0 + getsockname — আসল service-এর সঙ্গে কখনো সংঘর্ষ নয়।", "প্রথম recv-এর আগেই framing (দৈর্ঘ্য বা delimiter) নকশা করো।"] },
  "l4-pym-requests": { en: ["Status first, body second — an error page is not data.", "Tokens come from the environment; source code is a public place."], bn: ["আগে status, পরে body — error পৃষ্ঠা data নয়।", "Token environment থেকে আসে; source code সর্বজনীন জায়গা।"] },
  "l4-pym-threading": { en: ["Waiting work threads; computing work does not. Classify the task before pooling it.", "Data in as arguments, results out as returns — one collector, no shared state."], bn: ["অপেক্ষার কাজ thread হয়; হিসাবের কাজ হয় না। Pool করার আগে কাজ শ্রেণিবদ্ধ করো।", "Data argument হিসেবে ভেতরে, ফলাফল return হিসেবে বাইরে — এক সংগ্রাহক, shared state নেই।"] },
  "l4-pym-portscan": { en: ["Print the scope line in the tool's own output — authorisation travels with the report.", "Report 'closed/filtered' for silence; certainty beyond evidence misleads."], bn: ["Tool-এর নিজের output-এ scope লাইন ছাপো — অনুমোদন report-এর সঙ্গে ভ্রমণ করে।", "নীরবতার জন্য 'closed/filtered' report করো; প্রমাণের বাইরে নিশ্চয়তা বিভ্রান্ত করে।"] },
  "l4-pym-capstone": { en: ["Keep stages separate: when the source changes, only the parse stage should notice.", "Alerts without their tallies are unauditable — always ship the counts."], bn: ["ধাপ আলাদা রাখো: উৎস বদলালে শুধু parse ধাপ খেয়াল করবে।", "Tally ছাড়া alert অ-নিরীক্ষণযোগ্য — সবসময় count পাঠাও।"] },
